import {api,session,API_ORIGIN} from './auth.js';
import * as repository from './project-repository.js';
import {ensureBoard,activeBook,freshBook,addWell,addCurve,numericColumns,indexColumn,selectedObjects,rangeOf,curvePath,axisFor,depthFactor,palette,uid,finite,applyTemplate} from './well-canvas-model.js';

let ctx,key='',generation=0,loadingCount=0,search='',contextTarget=null,queue=[],outsideBound=false;
const cache=new Map(),failures=new Map(),pending=new Map(),undo=new Map(),redo=new Map();
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const board=()=>ensureBoard(ctx.state()),book=()=>activeBook(board()),data=()=>ctx.datasets();
const ds=id=>data().find(d=>d.id===id),col=(dataset,id)=>dataset?.columns?.find(c=>c.id===id),icon=id=>ctx.host.icon(id);
const fail=e=>ctx.host.toast(e.message||String(e));
const sourceUnit=c=>c?.effectiveUnit||c?.unit||'';
function normalizeScope(){const next=session.user?.uid+':'+ctx.project()?.id;if(key!==next){key=next;generation++;cache.clear();failures.clear();pending.clear();queue=[];loadingCount=0;search='';contextTarget=null;undo.clear();redo.clear();}}
export function configureWellCanvas(context){ctx=context;}
export function openCanvasAction(name){return action(name);}
export function canvasContext(){const b=book(),s=selectedObjects(b),curve=s.curve||s.track?.curves[0]||s.well?.tracks.flatMap(t=>t.curves)[0],dataset=ds(curve?.datasetId);if(!dataset)return null;if(dataset.isProposal)throw new Error('Review and accept this proposed result before using it as a downstream calculation input.');const index=col(dataset,curve.indexColumnId)||indexColumn(dataset);return {dataset,curve,well:s.well,scope:index&&depthFactor(sourceUnit(index))?{datasetId:dataset.id,columnId:index.id,unit:sourceUnit(index),reference:s.well?.basis||dataset.references?.depthReference||'Unconfirmed',...(b.selectionRange?{top:b.selectionRange.top,base:b.selectionRange.base}:{}),...(b.brush?.datasetId===dataset.id?{rowRanges:brushRanges(b.brush)}:{})}:null};}
function snapshot(){return JSON.stringify(board());}
function change(label,fn){const b=board(),before=snapshot(),history=undo.get(key)||[];history.push({label,state:before});if(history.length>30)history.shift();undo.set(key,history);redo.set(key,[]);fn();ctx.host.save();ctx.host.render();}
function redraw(){if(document.querySelector('.iw'))ctx.host.render();}
function select(well,track=null,curve=null){book().selected={wellId:well.id,trackId:track?.id,curveId:curve?.id};board().focus='logs';ctx.state().inspector=true;ctx.host.save();redraw();}
function allWells(){const names=new Set((ctx.host.getState().wellDrafts||[]).map(w=>w.id));for(const d of data())if(d.well)names.add(d.well);return [...names];}
function logDatasets(){return data().filter(d=>d.family==='logs'||d.family==='derived'&&indexColumn(d));}

async function readDataset(dataset){
 if(dataset.rowCount>250000||(dataset.rowCount||0)*(dataset.columns?.length||0)>12000000)throw new Error('This display supports up to 250,000 rows / 12 million scalar cells per dataset. Prepare a bounded dataset; no samples have been silently omitted.');
 const visible=new Set(book().wells.flatMap(w=>w.tracks.flatMap(t=>t.curves.map(c=>c.datasetId))));for(const [id] of cache)if(!visible.has(id)&&id!==dataset.id)cache.delete(id);
 if([...cache.values()].reduce((n,d)=>n+d.rowCount*d.columns.length,0)+(dataset.rowCount||0)*(dataset.columns?.length||0)>12000000)throw new Error('These visible datasets exceed the 12-million-cell display budget. Remove unused well displays or use a separate workbook.');
 let rows=[],columns=dataset.columns||[],metadata={},references=dataset.references||{};
 const p=ctx.project();
 if(p.storage==='cloud'&&dataset.isProposal){
  for(const chunk of dataset.chunks||[]){const response=await fetch(API_ORIGIN+`/api/projects/${encodeURIComponent(p.id)}/science/runs/${encodeURIComponent(dataset.scientificRunId)}/artifacts/${encodeURIComponent(chunk.name)}`,{headers:{Authorization:'Bearer '+await session.user.getIdToken()}});if(!response.ok)throw new Error('The proposed result chunk could not be opened.');const blob=await response.blob();if(blob.size>8*1024**2)throw new Error('The proposal chunk exceeds the reader budget.');const text=await new Response(blob.stream().pipeThrough(new DecompressionStream('gzip'))).text();if(text.length>64*1024**2)throw new Error('The expanded proposal chunk exceeds the reader budget.');for(const line of text.split('\n'))if(line.trim())rows.push(JSON.parse(line));}
 }else if(p.storage==='cloud'){
  for(let start=0;start<dataset.rowCount;start+=5000){const page=await api(`/api/projects/${p.id}/science/datasets/${dataset.id}/rows?start=${start}&limit=5000`);if(!page.rows.length)throw new Error('The stored row index ended before the dataset manifest. Refresh or inspect the source.');rows.push(...page.rows);columns=page.columns;metadata=page.metadata;references=page.references||references;}
 }else{
  const full=ctx.host.getState().ingestion?.imports?.find(i=>i.id===dataset.importId)?.datasets?.find(d=>d.id===dataset.id)||dataset;
  metadata=full.metadata||{};columns=full.columns;references=full.references||references;
  for(const chunk of full.chunks||[]){const blob=await repository.getArtifact(p,dataset.importId,chunk.name);if(blob.size>16*1024**2)throw new Error('This local chunk exceeds the bounded display reader.');const text=chunk.name.endsWith('.gz')?await new Response(blob.stream().pipeThrough(new DecompressionStream('gzip'))).text():await blob.text();if(text.length>64*1024**2)throw new Error('The expanded chunk exceeds the display memory budget.');for(const line of text.split('\n'))if(line.trim())rows.push(JSON.parse(line));}
 }
 if(rows.length!==dataset.rowCount)throw new Error('Stored samples do not match the dataset row count. No partial display has been marked complete.');
 return {rows,columns,metadata,references,rowCount:rows.length};
}
function restoreLegacyRange(){const s=board(),b=book(),visible=b.wells.filter(w=>w.tracks.some(t=>t.curves.length));if(s.rangeSafetyVersion||!visible.length||visible.some(w=>w.tracks.some(t=>t.curves.some(c=>!cache.has(c.datasetId)))))return;const extents=visible.map(w=>{const e=wellExtent(w),r=visibleRange(w),o=offsetFor(w);return e?{e:[e[0]-o,e[1]-o],r}:null;}).filter(Boolean);if(extents.length&&extents.every(({e,r})=>r[1]<e[0]||r[0]>e[1])){b.range=null;for(const w of visible)w.range=null;ctx.host.toast('Restored the displayed depth range to your loaded logs.');}s.rangeSafetyVersion=1;ctx.host.save();}
function pump(){while(loadingCount<2&&queue.length){const task=queue.shift(),g=generation;loadingCount++;readDataset(task.dataset).then(value=>{if(g===generation){cache.set(task.dataset.id,value);restoreLegacyRange();task.resolve(value);}}).catch(e=>{if(g===generation)failures.set(task.dataset.id,e.message);task.reject(e);}).finally(()=>{if(g===generation){loadingCount--;pending.delete(task.dataset.id);pump();redraw();}});}}
function load(dataset){if(!dataset)return Promise.reject(new Error('The source dataset is no longer active.'));if(cache.has(dataset.id))return Promise.resolve(cache.get(dataset.id));if(pending.has(dataset.id))return pending.get(dataset.id);const promise=new Promise((resolve,reject)=>queue.push({dataset,resolve,reject}));pending.set(dataset.id,promise);pump();return promise;}
function want(dataset){if(dataset&&!cache.has(dataset.id)&&!pending.has(dataset.id)&&!failures.has(dataset.id))queueMicrotask(()=>load(dataset).catch(()=>{}));}
function wellExtent(well){const values=[];for(const track of well.tracks)for(const c of track.curves){const source=cache.get(c.datasetId),dataset=ds(c.datasetId);if(!source)continue;const index=source.columns.findIndex(v=>v.id===(c.indexColumnId||indexColumn(dataset)?.id)),factor=depthFactor(sourceUnit(source.columns[index]));if(index<0||!factor)continue;const ext=rangeOf(source.rows.map(r=>finite(r[index])?r[index]*factor:null));if(ext)values.push(...ext);}return rangeOf(values);}
function fitRange(){const ranges=book().wells.flatMap(w=>{const r=wellExtent(w),offset=offsetFor(w);return r?[r[0]-offset,r[1]-offset]:[];});return rangeOf(ranges)||[0,1];}
function offsetFor(well){if(book().flatten){const marker=book().markers.find(m=>m.wellId===well.wellId&&m.name===book().flatten);if(marker)return marker.depth;}return Number(well.offset||0);}
function visibleRange(well){const b=book();return well.linked===false?well.range||wellExtent(well)||[0,1]:b.range||fitRange();}

export function wellBrowserView(){normalizeScope();const b=board(),wells=allWells(),query=search.toLowerCase();
 return `<aside class="iw-browser wb-browser" aria-label="Wells, runs and curves"><header><strong>Wells & curves</strong><button class="iw-icon" id="iw-browser-close" aria-label="Collapse project browser">${icon('close')}</button></header><label class="iw-search"><input id="wb-search" placeholder="Find well, run or curve…" aria-label="Find well, run or curve" value="${esc(search)}"></label><div class="wb-tree-actions"><button data-wb-action="register">${icon('plus')}Add well</button><button data-wb-action="import">${icon('upload')}Add curves</button></div><div class="wb-tree">${wells.map(id=>{const sources=logDatasets().filter(d=>d.well===id);if(query&&!(id+' '+sources.map(d=>d.name+' '+d.columns.map(c=>c.mnemonic).join(' ')).join(' ')).toLowerCase().includes(query))return '';return `<details data-wb-tree-well="${esc(id)}" data-wb-tree-key="well:${esc(id)}" ${query||board().treeOpen?.includes('well:'+id)?'open':''}><summary draggable="true" data-wb-drag='${esc(JSON.stringify({kind:'well',wellId:id}))}'><span>${icon('logs')}<strong>${esc(id)}</strong></span><button data-wb-open-well="${esc(id)}" title="Add this well to canvas" aria-label="Add ${esc(id)} to canvas">${icon('plus')}</button></summary><button class="wb-import-well" data-wb-import-well="${esc(id)}">Add a log run / curves…</button>${sources.map(d=>`<details class="wb-run" data-wb-tree-key="run:${esc(d.id)}" ${query||board().treeOpen?.includes('run:'+d.id)?'open':''}><summary>${icon('layers')}<span>${esc(d.name)}<small>${d.rowCount.toLocaleString()} samples · ${d.isProposal?esc(d.status):d.scientificRunId?'Calculated version':'Original run'}</small></span></summary>${numericColumns(d).filter(c=>c.id!==indexColumn(d)?.id&&(!query||(id+' '+d.name+' '+c.mnemonic).toLowerCase().includes(query))).map(c=>`<button class="wb-tree-curve" draggable="true" data-wb-drag='${esc(JSON.stringify({kind:'curve',wellId:id,datasetId:d.id,columnId:c.id}))}' data-wb-add-curve="${esc(d.id)}:${esc(c.id)}" data-wb-context='${esc(JSON.stringify({kind:'source',datasetId:d.id,columnId:c.id,wellId:id}))}'><span class="wb-curve-symbol">∿</span><span>${esc(c.mnemonic)}<small>${esc(sourceUnit(c)||'Unit unresolved')} · ${esc(c.id)}</small></span>${icon('plus')}</button>`).join('')}</details>`).join('')||'<p class="wb-muted">No log run retained for this well.</p>'}</details>`;}).join('')||'<p class="wb-muted">Register a well or import logs to start.</p>'}${data().filter(d=>!d.well||!logDatasets().some(l=>l.id===d.id)).length?`<details><summary>Other / unassigned datasets</summary>${data().filter(d=>!d.well||!logDatasets().some(l=>l.id===d.id)).map(d=>`<button data-wb-inspect="${esc(d.id)}">${esc(d.name)}<small>${esc(d.family)} · ${d.rowCount} records</small></button>`).join('')}</details>`:''}</div><div class="wb-tree-footer">Drag wells onto the canvas. Drag curves into tracks. Original data stays unchanged.</div></aside>`;
}

export function wellCanvasView(analysis=''){
 normalizeScope();const s=board(),b=book();
 if(!s.migrated){const legacy=ctx.state().windows.filter(w=>w.tool==='logs'&&w.datasetId);if(!legacy.length||legacy.every(w=>ds(w.datasetId))){for(const old of legacy){const dataset=ds(old.datasetId);if(!dataset)continue;const well=addWell(b,dataset.well||'Unassigned evidence',[]);for(const id of old.curves||numericColumns(dataset).filter(c=>c.id!==indexColumn(dataset)?.id).slice(0,3).map(c=>c.id)){const track=addCurve(well,dataset,id),curve=track.curves[0];Object.assign(curve,old.axes?.[id]||{});}if(old.depthColumn)for(const t of well.tracks)for(const c of t.curves)c.indexColumnId=old.depthColumn;old.closed=true;}s.migrated=true;ctx.host.save();}}
 for(const well of b.wells)for(const track of well.tracks)for(const curve of track.curves)want(ds(curve.datasetId));
 const selected=selectedObjects(b),range=b.range||fitRange(),outside=b.wells.some(w=>{const e=wellExtent(w),r=visibleRange(w),o=offsetFor(w);return e&&(r[1]<e[0]-o||r[0]>e[1]-o);});
 return `<div class="wb-studio ${ctx.state().grid===false?'wb-grid-off':''}" id="iw-canvas"><nav class="wb-workbooks" aria-label="Interpretation workbooks">${s.books.map(w=>`<button data-wb-book="${w.id}" aria-current="${w.id===s.activeBook?'page':'false'}">${icon('file')}${esc(w.name)}</button>`).join('')}<button class="iw-icon" data-wb-action="new-book" title="New workbook" aria-label="New workbook">${icon('plus')}</button><button class="iw-icon" data-wb-action="manage-book" title="Rename or close workbook" aria-label="Manage workbook">${icon('settings')}</button></nav>
 <div class="wb-controls"><div><button data-wb-action="undo" title="Undo display edit" aria-label="Undo" ${!(undo.get(key)?.length)?'disabled':''}>↶</button><button data-wb-action="redo" title="Redo display edit" aria-label="Redo" ${!(redo.get(key)?.length)?'disabled':''}>↷</button><button data-wb-action="zoom-in" aria-label="Zoom depth in" title="Zoom in">${icon('plus')}</button><button data-wb-action="zoom-out" aria-label="Zoom depth out" title="Zoom out">−</button><button data-wb-action="fit">Fit depth</button></div><div><button data-wb-action="all-wells">Add wells…</button><button data-wb-action="empty-track">Add track</button><button data-wb-action="tops">${b.pickTop?'Cancel top pick':'Pick top'}</button><button data-wb-action="crossplot">Crossplot</button><button data-wb-action="templates">Templates</button><button data-wb-action="recipes">Recipes</button><button data-wb-action="versions">History</button><button data-wb-action="export">Export</button></div></div>
 <div class="wb-depth-bar"><form id="wb-range"><label>Top <input name="top" type="number" step="any" aria-label="Canvas top depth in metres" value="${Number(range[0].toFixed(3))}"></label><label>Base <input name="base" type="number" step="any" aria-label="Canvas base depth in metres" value="${Number(range[1].toFixed(3))}"></label><button title="Apply depth range">Apply</button></form><span>m · ${esc(selected.well?.basis||'source reference retained')}</span><button data-wb-action="link" aria-pressed="${b.linked}">${b.linked?'Linked depths':'Independent depths'}</button><button data-wb-action="correlate" aria-pressed="${b.correlation}">${b.correlation?'Correlation on':'Correlate tops'}</button><button data-wb-action="flatten">${b.flatten?'Flattened: '+esc(b.flatten):'Flatten on top…'}</button>${b.selectionRange||b.brush?'<button data-wb-action="clear-selection">Clear interval / brush</button>':''}</div>
 ${(ctx.state().proposals||[]).length?`<div class="wb-proposal-bar">Proposed / reviewed comparisons · originals unchanged ${[...new Set(ctx.state().proposals.filter(d=>d.status.startsWith('Proposed')).map(d=>d.scientificRunId))].map(id=>`<button data-wb-review-run="${esc(id)}">Review calculated version</button>`).join("")}</div>`:""}${outside?`<div class="wb-range-warning" role="status">The displayed depth range is outside the loaded logs.<button data-wb-action="fit">Fit depth to logs</button></div>`:""}<div class="wb-board-scroll"><div class="wb-board ${b.pickTop?'wb-picking':''}" data-wb-drop="board">${b.wells.length?b.wells.map(wellView).join(''):`<div class="wb-empty"><span>${icon('logs')}</span><h2>Build your well-log canvas</h2><p>Drag a well from the tree, then drop curves into its tracks. Compare wells, pick tops and calculate from the selected evidence.</p><button class="primary" data-wb-action="all-wells">Choose wells to display</button><small>No curves, wells or results are generated for this empty canvas.</small></div>`}<div class="wb-drop-well" data-wb-drop="board">${icon('plus')}Drop a well here</div>${b.correlation?correlationLines():''}</div></div>
 ${b.crossplot?crossplotView():''}${s.focus==='analysis'&&analysis?`<section class="wb-analysis"><header><strong>Analysis · linked to canvas selection</strong><button data-wb-action="back-to-logs">Return to log properties ${icon('close')}</button></header>${analysis}</section>`:''}
 <footer class="wb-status"><span>${b.wells.length} wells · ${b.wells.reduce((n,w)=>n+w.tracks.length,0)} tracks · ${b.wells.some(w=>w.tracks.some(t=>t.curves.some(c=>!cache.has(c.datasetId)&&!failures.has(c.datasetId))))?'Loading full stored samples…':failures.size?'Review source loading errors':'Complete stored samples loaded'}</span><span id="wb-cursor-readout">${s.cursor?esc(s.cursor):'Click for values · Ctrl+wheel zoom · Shift+wheel pan · Shift-drag select'}</span></footer></div>`;
}
function wellView(well){const b=book(),width=60+well.tracks.reduce((n,t)=>n+t.width,0)+34,range=visibleRange(well),offset=offsetFor(well),count=new Set(well.tracks.flatMap(t=>t.curves.map(c=>c.datasetId)));
 return `<section class="wb-well ${b.selected?.wellId===well.id?'wb-active-well':''}" data-wb-well="${well.id}" style="width:${Math.max(240,width)}px"><header class="wb-well-heading" draggable="true" data-wb-drag='${esc(JSON.stringify({kind:'well-view',id:well.id}))}' data-wb-select='${esc(JSON.stringify({wellId:well.id}))}'><div><strong>${esc(well.name)}</strong><small>${count.size} runs · ${esc(well.basis||'Source depth reference')} · ${well.linked===false?'independent':'linked'}</small></div><button data-wb-well-menu="${well.id}" aria-label="Manage ${esc(well.name)}">⋯</button></header><div class="wb-tracks" data-wb-drop="well" data-well-id="${well.id}"><div class="wb-depth-track"><header><strong>${esc(well.basis||'Index')}</strong><small>metres ${offset?'· flattened':''}</small></header><svg viewBox="0 0 60 620" class="wb-depth-svg" aria-label="Depth ruler">${ticks(range).map(v=>`<text x="5" y="${(v-range[0])/(range[1]-range[0])*620+4}">${v.toFixed(range[1]-range[0]<20?2:0)}</text>`).join('')}</svg></div>${well.tracks.map((t,i)=>trackView(well,t,i,range,offset)).join('')}<button class="wb-add-track" data-wb-new-track="${well.id}" data-wb-drop="well" data-well-id="${well.id}" aria-label="Add track to ${esc(well.name)}">${icon('plus')}</button></div></section>`;
}
function ticks(range){return Array.from({length:11},(_,i)=>range[0]+(range[1]-range[0])*i/10);}
function trackView(well,track,i,range,offset){
 const selection=book().selected,isSelected=selection?.trackId===track.id,height=620;
 const paths=track.curves.filter(c=>c.visible).map(curve=>{const dataset=ds(curve.datasetId),source=cache.get(curve.datasetId);if(!source)return failures.has(curve.datasetId)?`<text x="5" y="35" class="wb-error-label">Source unavailable</text>`:`<text x="5" y="35" class="wb-error-label">Loading samples…</text>`;const ci=source.columns.findIndex(c=>c.id===curve.columnId),di=source.columns.findIndex(c=>c.id===(curve.indexColumnId||indexColumn(dataset)?.id)),factor=depthFactor(sourceUnit(source.columns[di]));if(!factor||di<0)return '<text x="5" y="35" class="wb-error-label">Confirm depth index/unit</text>';const axis=axisFor(source.rows,ci,curve);if(!axis)return '<text x="5" y="35" class="wb-error-label">No finite values in scale</text>';const path=curvePath(source.rows,di,ci,range,axis,track.width-12,height,offset,factor);return `${!path?'<text x="8" y="44" class="wb-error-label">No samples in this interval</text>':''}<g transform="translate(6 0)"><path data-wb-curve-path="${curve.id}" d="${path}" stroke="${esc(curve.color)}" stroke-width="${isSelected&&selection.curveId===curve.id?1.8:1.15}" fill="none" ${curve.dashed?'stroke-dasharray="4 3"':''} vector-effect="non-scaling-stroke"/><text x="0" y="12" class="wb-axis-label" fill="${esc(curve.color)}">${axis.log?Math.pow(10,axis[0]).toPrecision(3):Number(axis[0].toPrecision(4))}</text><text x="${track.width-14}" y="12" text-anchor="end" class="wb-axis-label" fill="${esc(curve.color)}">${axis.log?Math.pow(10,axis[1]).toPrecision(3):Number(axis[1].toPrecision(4))}</text></g>`;}).join('');
 const bands=selectionBands(well,track,range,offset),tops=book().markers.filter(m=>m.wellId===well.wellId).map(m=>{const y=(m.depth-offset-range[0])/(range[1]-range[0])*height;return y<0||y>height?'':`<g class="wb-top"><line x1="0" x2="${track.width}" y1="${y}" y2="${y}" stroke="${esc(m.color||'#b78540')}" stroke-width="1.2"/><text x="5" y="${y-4}">${esc(m.name)}</text></g>`;}).join('');
 return `<div class="wb-track ${isSelected?'wb-active-track':''}" style="width:${track.width}px" data-wb-track="${track.id}" data-wb-drop="track" data-well-id="${well.id}" data-track-id="${track.id}" data-wb-context='${esc(JSON.stringify({kind:'track',wellId:well.id,trackId:track.id}))}'><header draggable="true" data-wb-drag='${esc(JSON.stringify({kind:'track',wellId:well.id,trackId:track.id}))}'><button data-wb-select='${esc(JSON.stringify({wellId:well.id,trackId:track.id}))}'>${esc(track.name)}</button>${track.curves.map(c=>`<button class="wb-curve-chip ${selection?.curveId===c.id?'selected':''}" data-wb-select='${esc(JSON.stringify({wellId:well.id,trackId:track.id,curveId:c.id}))}' data-wb-context='${esc(JSON.stringify({kind:'curve',wellId:well.id,trackId:track.id,curveId:c.id}))}' style="color:${esc(c.color)}"><span>${c.visible?'∿':'○'} ${esc(c.name)}</span><small>${esc(c.unit||'unit unresolved')}${c.dashed?' · overlay':''}${c.log?' · log':''}${ds(c.datasetId)?.scientificRunId?' · derived':''}</small></button>`).join('')}</header><svg class="wb-track-plot" data-wb-plot="${track.id}" data-well-id="${well.id}" viewBox="0 0 ${track.width} 620" preserveAspectRatio="none" tabindex="0" role="img" aria-label="${esc(well.name)} ${esc(track.name)} real log samples"><defs><clipPath id="clip-${track.id}"><rect width="${track.width}" height="620"/></clipPath></defs><rect width="${track.width}" height="620" fill="white"/>${Array.from({length:6},(_,j)=>`<line x1="${j*track.width/5}" x2="${j*track.width/5}" y1="0" y2="620" stroke="#eaf0ed"/>`).join('')}${ticks(range).map(d=>`<line x1="0" x2="${track.width}" y1="${(d-range[0])/(range[1]-range[0])*620}" y2="${(d-range[0])/(range[1]-range[0])*620}" stroke="#dce7e2"/>`).join('')}<g clip-path="url(#clip-${track.id})">${bands}${paths}${tops}</g><line class="wb-cursor-line" x1="0" x2="${track.width}" y1="-10" y2="-10" stroke="#294b45" stroke-dasharray="3 2"/></svg><footer>${track.curves.map(c=>{const p=cache.get(c.datasetId);return `<span>${p?p.rowCount.toLocaleString():'…'} ${esc(c.name)}</span>`;}).join('')}</footer><button class="wb-insert-track" data-wb-insert="${well.id}:${i}" aria-label="Insert track before ${esc(track.name)}"></button></div>`;
}
function selectionBands(well,track,range,offset){const b=book(),intervals=[];if(b.selectionRange)intervals.push([b.selectionRange.top-offset,b.selectionRange.base-offset]);if(b.brush){const source=cache.get(b.brush.datasetId),dataset=ds(b.brush.datasetId),idx=source?.columns.findIndex(c=>c.id===indexColumn(dataset)?.id),factor=depthFactor(sourceUnit(source?.columns[idx]));if(source&&dataset.well===well.wellId&&factor){const selected=brushedIndices(b.brush);let first=null,last=null;for(const i of selected){const z=source.rows[i][idx]*factor-offset;if(first===null)first=z;else if(i!==last+1){intervals.push([first,source.rows[last][idx]*factor-offset]);first=z;}last=i;}if(first!==null)intervals.push([first,source.rows[last][idx]*factor-offset]);}}
 return intervals.map(([top,base])=>`<rect x="0" y="${(top-range[0])/(range[1]-range[0])*620}" width="${track.width}" height="${Math.max(2,(base-top)/(range[1]-range[0])*620)}" fill="#d2a454" opacity=".18"/>`).join('');}
function correlationLines(){let left=0,previous=null,lines=[];for(const well of book().wells){const width=Math.max(240,60+well.tracks.reduce((n,t)=>n+t.width,0)+34),range=visibleRange(well),offset=offsetFor(well),points=book().markers.filter(m=>m.wellId===well.wellId).map(m=>({name:m.name,y:128+(m.depth-offset-range[0])/(range[1]-range[0])*620}));if(previous)for(const p of points){const from=previous.points.find(v=>v.name===p.name);if(from&&p.y>=128&&p.y<=748&&from.y>=128&&from.y<=748)lines.push(`<line x1="${previous.right}" x2="${left+60}" y1="${from.y}" y2="${p.y}" stroke="#b58c50" stroke-width="1" stroke-dasharray="4 3"/>`);}previous={points,right:left+width-34};left+=width+24;}return `<svg class="wb-correlations" width="${left}" height="780" aria-label="User-picked formation-top correlations">${lines.join('')}</svg>`;}

export function wellInspectorView(){const {well,track,curve}=selectedObjects(book());
 if(!well)return `<aside class="iw-inspector wb-inspector"><header><strong>Canvas properties</strong><button class="iw-icon" id="iw-inspector-close" aria-label="Collapse properties">${icon('close')}</button></header><div class="iw-inspector-empty">Select a well, track or curve on the canvas. Drag wells and curves from the tree to build your display.</div></aside>`;
 const dataset=ds(curve?.datasetId),source=cache.get(curve?.datasetId),column=col(dataset,curve?.columnId);
 return `<aside class="iw-inspector wb-inspector"><header><strong>${curve?'Curve properties':track?'Track properties':'Well properties'}</strong><button class="iw-icon" id="iw-inspector-close" aria-label="Collapse properties">${icon('close')}</button></header><div class="wb-selection-summary"><strong>${esc(well.name)}</strong><span>${esc(track?.name||'Well display')}${curve?' / '+esc(curve.name):''}</span></div><form id="wb-properties"><label class="field">Display name<input name="name" required maxlength="120" value="${esc(curve?.name||track?.name||well.name)}"></label>${curve?`<label class="field">Line colour<input name="color" type="color" value="${esc(curve.color)}"></label><label class="iw-check"><input type="checkbox" name="visible" ${curve.visible?'checked':''}>Visible</label><label class="iw-check"><input type="checkbox" name="log" ${curve.log?'checked':''}>Logarithmic axis</label><label class="iw-check"><input type="checkbox" name="reverse" ${curve.reverse?'checked':''}>Reverse axis</label><label class="iw-check"><input type="checkbox" name="dashed" ${curve.dashed?'checked':''}>Dashed / ghost overlay</label><div class="wb-two-fields"><label class="field">Axis minimum<input name="min" type="number" step="any" value="${curve.min??''}" placeholder="Auto"></label><label class="field">Axis maximum<input name="max" type="number" step="any" value="${curve.max??''}" placeholder="Auto"></label></div><label class="field">Depth/index column<select name="indexColumnId" required>${numericColumns(dataset||{}).map(c=>`<option value="${esc(c.id)}" ${c.id===curve.indexColumnId?'selected':''}>${esc(c.mnemonic)} · ${esc(sourceUnit(c)||'unit unresolved')}</option>`).join('')}</select></label>`:''}${track?`<label class="field">Track width (px)<input name="width" type="number" min="80" max="360" value="${track.width}"></label>`:''}<label class="field">Display depth reference<select name="basis">${['Source reference','MD','TVD','TVDSS'].map(v=>`<option ${well.basis===v?'selected':''}>${v}</option>`).join('')}</select><small>Changing the label does not convert measured depth or calculate a trajectory.</small></label><label class="iw-check"><input name="linked" type="checkbox" ${well.linked!==false?'checked':''}>Link depth navigation for this well</label><label class="field">Display depth offset (m)<input name="offset" type="number" step="any" value="${well.offset||0}"></label><p id="wb-properties-error" role="alert"></p><button class="primary" type="submit">Apply display settings</button></form><div class="wb-inspector-actions">${track?'<button data-wb-action="duplicate-track">Duplicate track</button><button data-wb-action="remove-track">Remove track from view</button>':''}${curve?'<button data-wb-action="curve-export">Export curve CSV</button><button data-wb-action="provenance">Source & provenance</button><button data-wb-action="calculate">Calculate from selection…</button><button data-wb-action="remove-curve">Remove curve from view</button>':''}<button data-wb-import-well="${esc(well.wellId)}">Add curves to this well…</button></div>${curve?`<section class="wb-provenance"><h3>${dataset?.scientificRunId?'Calculated curve version':'Original source curve'}</h3><p>${esc(dataset?.name)} · ${esc(column?.mnemonic)} (${esc(column?.id)})</p><p>Source unit: ${esc(sourceUnit(column)||'Unresolved')} · ${source?source.rowCount.toLocaleString():'Loading'} retained samples</p><p>${dataset?.scientificRunId?'Derived result; activation does not grant scientific approval.':'Display edits never change original samples.'}</p>${failures.has(dataset?.id)?`<p role="alert">${esc(failures.get(dataset.id))}</p><button data-wb-retry="${esc(dataset.id)}">Retry source loading</button>`:''}</section>`:''}</aside>`;
}

function brandedForm(title,body,onSubmit){ctx.host.modal(title,`<form id="wb-dialog-form">${body}<p id="wb-dialog-error" role="alert"></p><button class="primary" type="submit">Save</button></form>`);$('#wb-dialog-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{await onSubmit(new FormData(e.target));$('#dialog').close();redraw();}catch(error){$('#wb-dialog-error').textContent=error.message;button.disabled=false;}};}
function openWell(id){change('Add well display',()=>{addWell(book(),id,logDatasets());board().focus='logs';});}
function chooseWells(){ctx.host.modal('Add wells to canvas',`<p>Choose registered wells. This adds displays; it does not duplicate source files.</p><form id="wb-choose-wells">${allWells().map(id=>`<label class="iw-check"><input type="checkbox" name="well" value="${esc(id)}" ${book().wells.some(w=>w.wellId===id)?'checked':''}>${esc(id)}</label>`).join('')||'<p>No wells registered. Use Add well or import a LAS run.</p>'}<button class="primary">Add selected wells</button></form>`);$('#wb-choose-wells').onsubmit=e=>{e.preventDefault();const ids=new FormData(e.target).getAll('well');change('Add wells to canvas',()=>{for(const id of ids)addWell(book(),id,logDatasets());board().focus='logs';});$('#dialog').close();};}
function registerWell(){brandedForm('Register a well',`<label class="field">Well identifier<input name="id" required maxlength="100" placeholder="For example: TMB-01"></label><p>Register an identity first, then add its source log runs. No curves or coordinates are invented.</p>`,async f=>{const id=String(f.get('id')).trim();if(!id)throw new Error('Enter a well identifier.');if(allWells().some(w=>w.toLowerCase()===id.toLowerCase()))throw new Error('This well is already registered. Add another log run to the existing well.');ctx.host.getState().wellDrafts||=[];ctx.host.getState().wellDrafts.push({id,status:'User registered',createdAt:new Date().toISOString()});ctx.host.save();await ctx.host.flush();openWell(id);});}
function addToTrack(payload,wellId=null,trackId=null,at=null){
 if(payload.kind==='well'){openWell(payload.wellId);return;}
 if(payload.kind==='well-view'){change('Reorder wells',()=>{const wells=book().wells,index=wells.findIndex(w=>w.id===payload.id),target=wells.findIndex(w=>w.id===wellId);if(index<0)return;const [w]=wells.splice(index,1);wells.splice(target<0?wells.length:target,0,w);});return;}
 if(payload.kind==='track'){change('Move track',()=>{const from=book().wells.find(w=>w.id===payload.wellId),to=book().wells.find(w=>w.id===wellId);if(!from||!to)return;const index=from.tracks.findIndex(t=>t.id===payload.trackId);if(index<0)return;const [track]=from.tracks.splice(index,1);const position=to.tracks.findIndex(t=>t.id===trackId);to.tracks.splice(at??(position<0?to.tracks.length:position),0,track);});return;}
 const dataset=ds(payload.datasetId);if(!dataset)throw new Error('The selected source is not active.');change('Add source curve',()=>{let well=book().wells.find(w=>w.id===wellId)||book().wells.find(w=>w.wellId===dataset.well);if(!well)well=addWell(book(),dataset.well||'Unassigned evidence',[]);const track=addCurve(well,dataset,payload.columnId,trackId);if(at!==null){well.tracks=well.tracks.filter(t=>t.id!==track.id);well.tracks.splice(at,0,track);}book().selected={wellId:well.id,trackId:track.id,curveId:track.curves.at(-1).id};board().focus='logs';});
}
function zoom(factor,center=null,well=null){if(!book().wells.some(w=>wellExtent(w)))throw new Error('Wait for the retained log samples to load before changing depth.');change('Depth navigation',()=>{const w=well||selectedObjects(book()).well,range=w?visibleRange(w):book().range||fitRange(),mid=center??(range[0]+range[1])/2,span=Math.max(.001,(range[1]-range[0])*factor),t=(mid-range[0])/(range[1]-range[0]);const next=[mid-span*t,mid+span*(1-t)];if(w&&w.linked===false)w.range=next;else book().range=next;});}
function pickTop(well,depth){brandedForm('Pick a formation top',`<label class="field">Formation / marker name<input name="name" required maxlength="100"></label><label class="field">Source depth (metres)<input name="depth" type="number" step="any" required value="${depth.toFixed(4)}"></label><label class="field">Evidence / uncertainty notes<textarea name="notes" required maxlength="2000"></textarea></label><p>${esc(well.wellId)} · ${esc(well.basis||'source reference')}. A matching name on another well draws a user-picked correlation, not an automatic geological interpretation.</p>`,f=>{change('Pick formation top',()=>{book().markers.push({id:uid(),wellId:well.wellId,name:f.get('name').trim(),depth:Number(f.get('depth')),notes:f.get('notes'),reference:well.basis||'Source reference',color:'#b78540',createdAt:new Date().toISOString()});book().pickTop=false;});});}
function provenance(curve){const dataset=ds(curve.datasetId),c=col(dataset,curve.columnId);if(!dataset||!c)throw new Error('This original source is no longer active. Restore it before opening provenance.');ctx.host.modal('Curve source and provenance',`<h3>${esc(curve.name)}</h3><dl class="iw-metrics">${Object.entries({well:dataset.well,run:dataset.name,originalMnemonic:c.mnemonic,columnIdentity:c.id,sourceUnit:sourceUnit(c)||'Unresolved',sourceFingerprint:dataset.sourceSha256||'Not recorded',parserVersion:dataset.parserVersion||'',calculationRun:dataset.scientificRunId||'Original evidence',reviewState:dataset.scientificApproval?'Scientifically approved':'Scientific approval not granted'}).map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><p>Display labels, colours and axis settings do not modify stored samples.</p>`);}
function templates(){const {well}=selectedObjects(book());if(!well)throw new Error('Select a well before saving or applying a display template.');const b=board();ctx.host.modal('Track templates',`<div class="wb-template-actions"><button id="wb-save-template">Save selected well as template</button></div>${b.templates.map(t=>`<div class="status-row"><span>${esc(t.name)}</span><button data-wb-apply-template="${t.id}">Apply to selected well</button></div>`).join('')||'<p>No saved templates.</p>'}<p>Templates match exact mnemonic and unit. Ambiguous/missing runs are reported for review.</p>`);$('#wb-save-template').onclick=()=>brandedForm('Save track template','<label class="field">Template name<input name="name" required maxlength="100"></label>',f=>{change('Save track template',()=>{b.templates.push({id:uid(),name:f.get('name'),tracks:well.tracks.map(t=>({name:t.name,width:t.width,curves:t.curves.map(c=>({mnemonic:col(ds(c.datasetId),c.columnId)?.mnemonic,unit:c.unit,color:c.color,log:c.log,reverse:c.reverse,min:c.min,max:c.max}))}))});});});document.querySelectorAll('[data-wb-apply-template]').forEach(button=>button.onclick=()=>{let missing=[];change('Apply display template',()=>missing=applyTemplate(well,b.templates.find(t=>t.id===button.dataset.wbApplyTemplate),data()));$('#dialog').close();if(missing.length)ctx.host.modal('Template needs review',`<p>Exact matches were applied. No curve was guessed for:</p><ul>${missing.map(v=>`<li>${esc(v)}</li>`).join('')}</ul>`);});}
function versions(){const b=board();ctx.host.modal('Workbook versions',`<button id="wb-save-version">Save named workbook version</button>${b.versions.map(v=>`<div class="status-row"><span>${esc(v.name)}<small>${esc(new Date(v.time).toLocaleString())}</small></span><button data-wb-restore-version="${v.id}">Restore display</button></div>`).join('')||'<p>No saved versions. Undo/redo tracks edits during this session.</p>'}`);$('#wb-save-version').onclick=()=>brandedForm('Save workbook version','<label class="field">Version name<input name="name" required maxlength="100"></label>',f=>change('Save workbook version',()=>{b.versions.push({id:uid(),name:f.get('name'),time:new Date().toISOString(),book:structuredClone(book())});if(b.versions.length>5)b.versions.shift();}));document.querySelectorAll('[data-wb-restore-version]').forEach(button=>button.onclick=()=>{change('Restore workbook version',()=>{const saved=b.versions.find(v=>v.id===button.dataset.wbRestoreVersion);const current=book();const restored=structuredClone(saved.book);restored.id=current.id;b.books[b.books.indexOf(current)]=restored;});$('#dialog').close();});}
function recipes(){const b=board();ctx.host.modal('Reviewed workflow recipes',`<p>Recipes reopen saved method configurations for the selected well. Each step must be mapped, confirmed and run explicitly; results are never invented or automatically chained.</p><button id="wb-save-recipe">Save current analysis steps</button>${b.recipes.map(r=>`<div class="status-row"><span>${esc(r.name)} · ${r.steps.length} steps</span><button data-wb-open-recipe="${r.id}">Open steps</button></div>`).join('')}`);$('#wb-save-recipe').onclick=()=>{const steps=ctx.state().windows.filter(w=>w.method&&w.tool!=='logs').map(w=>({method:w.method,parameters:structuredClone(w.parameters||{}),notes:w.notes||''}));if(!steps.length){ctx.host.toast('Configure at least one analysis step first.');return;}brandedForm('Save workflow recipe','<label class="field">Recipe name<input name="name" required maxlength="100"></label>',f=>change('Save recipe',()=>b.recipes.push({id:uid(),name:f.get('name'),steps})));};document.querySelectorAll('[data-wb-open-recipe]').forEach(button=>button.onclick=()=>{const r=b.recipes.find(r=>r.id===button.dataset.wbOpenRecipe);$('#dialog').close();for(const step of r.steps)ctx.openMethod(step.method,step);});}

function crossplotSetup(){const {curve,well,track}=selectedObjects(book()),dataset=ds(curve?.datasetId||track?.curves[0]?.datasetId||well?.tracks[0]?.curves[0]?.datasetId);if(!dataset)throw new Error('Select a source curve before opening a crossplot.');brandedForm('Crossplot from selected well',`<p>${esc(dataset.well)} · ${esc(dataset.name)}. Both axes use the same stored rows; no implicit resampling.</p>${['x','y'].map((role,j)=>`<label class="field">${role.toUpperCase()} curve<select name="${role}">${numericColumns(dataset).filter(c=>c.id!==indexColumn(dataset)?.id).map((c,i)=>`<option value="${c.id}" ${i===j?'selected':''}>${esc(c.mnemonic)} · ${esc(sourceUnit(c)||'unresolved')}</option>`).join('')}</select></label>`).join('')}`,async f=>{if(f.get('x')===f.get('y'))throw new Error('Choose two different columns.');await load(dataset);change('Open crossplot',()=>book().crossplot={datasetId:dataset.id,x:f.get('x'),y:f.get('y')});});}
function brushedIndices(brush){const source=cache.get(brush.datasetId);if(!source)return [];const x=source.columns.findIndex(c=>c.id===brush.x),y=source.columns.findIndex(c=>c.id===brush.y);return source.rows.flatMap((r,i)=>finite(r[x])&&finite(r[y])&&r[x]>=brush.xmin&&r[x]<=brush.xmax&&r[y]>=brush.ymin&&r[y]<=brush.ymax?[i]:[]);}
function brushRanges(brush){const indices=brushedIndices(brush),ranges=[];for(const i of indices){const last=ranges.at(-1);if(last&&last[1]===i-1)last[1]=i;else ranges.push([i,i]);}if(ranges.length>1000)throw new Error('Refine the crossplot brush to at most 1,000 contiguous row ranges before calculating.');return ranges;}
function crossplotView(){const config=book().crossplot,source=cache.get(config.datasetId),dataset=ds(config.datasetId);if(!source)return '';const xi=source.columns.findIndex(c=>c.id===config.x),yi=source.columns.findIndex(c=>c.id===config.y),xr=rangeOf(source.rows.map(r=>r[xi])),yr=rangeOf(source.rows.map(r=>r[yi]));if(!xr||!yr)return '<section class="wb-crossplot"><p>No finite pairs for this crossplot.</p><button data-wb-action="close-crossplot">Close</button></section>';const valid=source.rows.map((r,i)=>({r,i})).filter(p=>finite(p.r[xi])&&finite(p.r[yi])),step=Math.max(1,Math.ceil(valid.length/2000)),di=source.columns.findIndex(c=>c.id===indexColumn(dataset)?.id),factor=depthFactor(sourceUnit(source.columns[di]));const selected=new Set(book().brush?brushedIndices(book().brush):[]);
 return `<section class="wb-crossplot"><header><strong>${esc(dataset.well)} · ${esc(col(dataset,config.x)?.mnemonic)} × ${esc(col(dataset,config.y)?.mnemonic)}</strong><button data-wb-action="close-crossplot" aria-label="Close crossplot">${icon('close')}</button></header><p>Drag to brush points. Full retained pairs determine selection; at most 2,000 are drawn.</p><svg id="wb-crossplot-svg" viewBox="0 0 600 300" role="img" aria-label="Linked source crossplot" data-xmin="${xr[0]}" data-xmax="${xr[1]}" data-ymin="${yr[0]}" data-ymax="${yr[1]}"><path d="M45 15v245h535" stroke="#a5b9af" fill="none"/>${valid.filter((_,i)=>i%step===0).map(({r,i})=>{const z=factor&&finite(r[di])?r[di]*factor:null,interval=book().selectionRange,active=selected.has(i)||interval&&finite(z)&&z>=interval.top&&z<=interval.base;return `<circle cx="${45+(r[xi]-xr[0])/(xr[1]-xr[0])*525}" cy="${260-(r[yi]-yr[0])/(yr[1]-yr[0])*240}" r="${active?2.5:1.6}" fill="${active?'#b78540':'#087c73'}" opacity=".65"/>`;}).join('')}<text x="45" y="285">${xr[0].toPrecision(4)}</text><text x="510" y="285">${xr[1].toPrecision(4)}</text><text x="2" y="25">${yr[1].toPrecision(4)}</text><text x="2" y="260">${yr[0].toPrecision(4)}</text><rect id="wb-brush-rect" fill="#b78540" opacity=".15" width="0" height="0"/></svg><small>${valid.length.toLocaleString()} valid pairs${book().brush?' · '+selected.size.toLocaleString()+' brushed samples':''} · X ${esc(sourceUnit(col(dataset,config.x))||'unit unresolved')} · Y ${esc(sourceUnit(col(dataset,config.y))||'unit unresolved')}</small></section>`;
}

function exportCurve(curve){const source=cache.get(curve.datasetId),dataset=ds(curve.datasetId);if(!source)throw new Error('Wait for the complete source to load before exporting.');const ci=source.columns.findIndex(c=>c.id===curve.columnId),di=source.columns.findIndex(c=>c.id===(curve.indexColumnId||indexColumn(dataset)?.id));if(di<0)throw new Error('Select a depth/index column first.');const quote=v=>'"'+(typeof v==='string'&&/^[=+@-]/.test(v)?"'"+v:String(v??'')).replaceAll('"','""')+'"';const text=[[source.columns[di].mnemonic+' ['+sourceUnit(source.columns[di])+']',source.columns[ci].mnemonic+' ['+sourceUnit(source.columns[ci])+']'],...source.rows.map(r=>[r[di],r[ci]])].map(row=>row.map(quote).join(',')).join('\r\n');ctx.host.download('StrataX-'+curve.name.replace(/[^\w-]/g,'_')+'.csv',new Blob([text],{type:'text/csv'}));}
function exportView(){const b=book();ctx.host.modal('Export workbook',`<p>Export the actual displayed curves and picked tops, or retain the editable view metadata. Original files stay in project storage.</p><div class="actions"><button id="wb-export-svg">Export plotted SVG</button><button id="wb-export-layout">Export view metadata</button><button id="wb-import-layout">Import view metadata</button></div>`);$('#wb-export-layout').onclick=()=>ctx.host.download('StrataX-view.json',new Blob([JSON.stringify({schemaVersion:1,projectId:ctx.project().id,book:b},null,2)],{type:'application/json'}));$('#wb-import-layout').onclick=()=>{const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{try{const file=input.files[0];if(file.size>512000)throw new Error('Choose view metadata below 500 KiB.');const parsed=JSON.parse(await file.text());if(parsed.schemaVersion!==1||parsed.projectId!==ctx.project().id||!Array.isArray(parsed.book?.wells)||parsed.book.wells.length>30)throw new Error('Choose a view exported from this project.');const clean=validateBook(parsed.book);change('Import workbook view',()=>{clean.id=uid();board().books.push(clean);board().activeBook=clean.id;});$('#dialog').close();}catch(e){fail(e);}};input.click();};$('#wb-export-svg').onclick=()=>{let x=0,elements=[];for(const well of document.querySelectorAll('.wb-well')){const width=well.offsetWidth;elements.push(`<text x="${x+10}" y="22" font-family="sans-serif" font-size="14">${esc(book().wells.find(w=>w.id===well.dataset.wbWell).name)}</text>`);let tx=x;for(const track of well.querySelectorAll('.wb-depth-track,.wb-track')){const svg=track.querySelector('svg');if(svg){const copy=svg.cloneNode(true);copy.setAttribute('width',track.offsetWidth);copy.setAttribute('height','620');elements.push(`<g transform="translate(${tx} 125)">${copy.outerHTML}</g>`);const header=track.querySelector('header')?.innerText||'';header.split('\n').slice(0,5).forEach((line,j)=>elements.push(`<text x="${tx+5}" y="${45+j*14}" font-family="sans-serif" font-size="10">${esc(line)}</text>`));}tx+=track.offsetWidth;}x+=width+24;}ctx.host.download('StrataX-workbook.svg',new Blob([`<svg xmlns="http://www.w3.org/2000/svg" width="${Math.max(600,x)}" height="800"><rect width="100%" height="100%" fill="white"/>${elements.join('')}<text x="10" y="785" font-family="sans-serif" font-size="10">Stored source curves · displayed min/max envelope · source references retained · ${esc(b.name)}</text></svg>`],{type:'image/svg+xml'}));};}
function validateBook(value){const result=freshBook(String(value.name||'Imported workbook').slice(0,100));result.range=validRange(value.range)?value.range:null;for(const w of value.wells){if(typeof w.wellId!=='string'||!Array.isArray(w.tracks)||w.tracks.length>30)throw new Error('Invalid well/track metadata.');const well={id:uid(),wellId:w.wellId,name:String(w.name||w.wellId).slice(0,120),tracks:[],offset:finite(w.offset)?w.offset:0,linked:w.linked!==false,basis:['MD','TVD','TVDSS','Source reference'].includes(w.basis)?w.basis:'Source reference'};for(const t of w.tracks){if(!Array.isArray(t.curves)||t.curves.length>12)throw new Error('Invalid track metadata.');const track={id:uid(),name:String(t.name||'Track').slice(0,120),width:Math.max(80,Math.min(360,Number(t.width)||140)),curves:[]};well.tracks.push(track);for(const c of t.curves){const dataset=ds(c.datasetId);if(!dataset||!col(dataset,c.columnId))throw new Error('The imported view references an unavailable source.');addCurve(well,dataset,c.columnId,track.id);const curve=track.curves.at(-1);for(const prop of ['log','reverse','dashed','visible'])if(typeof c[prop]==='boolean')curve[prop]=c[prop];if(/^#[0-9a-f]{6}$/i.test(c.color))curve.color=c.color;for(const prop of ['min','max'])curve[prop]=finite(c[prop])?c[prop]:null;curve.name=String(c.name||curve.name).slice(0,120);if(c.indexColumnId&&col(dataset,c.indexColumnId))curve.indexColumnId=c.indexColumnId;if(c.indexColumnId&&col(dataset,c.indexColumnId))curve.indexColumnId=c.indexColumnId;}}well.range=validRange(w.range)?w.range:null;result.wells.push(well);}result.markers=(Array.isArray(value.markers)?value.markers:[]).slice(0,500).map(m=>{if(!finite(m.depth)||typeof m.wellId!=='string'||typeof m.name!=='string')throw new Error('Invalid picked-top metadata.');return {id:uid(),wellId:m.wellId,name:m.name.slice(0,100),depth:m.depth,notes:String(m.notes||'').slice(0,2000),reference:String(m.reference||'Source reference').slice(0,80),color:'#b78540'};});result.flatten=typeof value.flatten==='string'?value.flatten.slice(0,100):null;result.correlation=value.correlation===true;return result;}
const validRange=r=>Array.isArray(r)&&r.length===2&&r.every(finite)&&r[1]>r[0];

function contextMenu(target,x,y){contextTarget=target;document.querySelector('#wb-context-menu')?.remove();const menu=document.createElement('div');menu.id='wb-context-menu';menu.className='wb-context-menu';menu.setAttribute('role','menu');const actions=target.kind==='source'?[['add','Add to canvas'],['source-provenance','Source provenance']]:target.kind==='curve'?[['properties','Curve properties'],['duplicate-curve','Duplicate overlay'],['crossplot','Crossplot'],['calculate','Calculate from selection'],['curve-export','Export curve CSV'],['provenance','Source & provenance'],['remove-curve','Remove from view']]:[['properties','Track properties'],['duplicate-track','Duplicate track'],['remove-track','Remove from view']];menu.innerHTML=actions.map(([id,label])=>`<button role="menuitem" data-wb-context-action="${id}">${label}</button>`).join('');menu.style.left=Math.max(8,Math.min(x,innerWidth-230))+'px';menu.style.top=Math.max(8,Math.min(y,innerHeight-actions.length*36-12))+'px';document.body.append(menu);menu.querySelector('button')?.focus();menu.querySelectorAll('button').forEach(button=>button.onclick=()=>{menu.remove();try{if(target.kind==='source'){if(button.dataset.wbContextAction==='add')addToTrack({...target,kind:'curve'});else provenance({datasetId:target.datasetId,columnId:target.columnId,name:col(ds(target.datasetId),target.columnId)?.mnemonic});return;}book().selected={wellId:target.wellId,trackId:target.trackId,curveId:target.curveId};action(button.dataset.wbContextAction);}catch(e){fail(e);}});menu.onkeydown=e=>{const buttons=[...menu.querySelectorAll('button')],i=buttons.indexOf(document.activeElement);if(e.key==='Escape'){menu.remove();return;}if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();buttons[(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length].focus();}};}

function action(name){const b=book(),s=board(),{well,track,curve}=selectedObjects(b);switch(name){
 case 'register':return registerWell();case 'import':return ctx.host.openImporter({family:'logs',well:well?.wellId});case 'all-wells':return chooseWells();case 'crossplot':return crossplotSetup();case 'templates':return templates();case 'recipes':return recipes();case 'versions':return versions();case 'export':return exportView();
 case 'new-book':return brandedForm('New workbook','<label class="field">Name<input name="name" required maxlength="100"></label>',f=>change('Create workbook',()=>{const w=freshBook(f.get('name'));s.books.push(w);s.activeBook=w.id;}));
 case 'manage-book':return brandedForm('Manage workbook',`<label class="field">Name<input name="name" required maxlength="100" value="${esc(b.name)}"></label><label class="iw-check"><input name="close" type="checkbox" ${s.books.length===1?'disabled':''}>Close this workbook (source data is retained)</label>`,f=>change('Manage workbook',()=>{if(f.has('close')){s.books=s.books.filter(w=>w.id!==b.id);s.activeBook=s.books[0].id;}else b.name=f.get('name');}));
 case 'undo':case 'redo':{const from=name==='undo'?undo:redo,to=name==='undo'?redo:undo,stack=from.get(key)||[],entry=stack.pop();if(!entry)return;const reverse=to.get(key)||[];reverse.push({label:entry.label,state:snapshot()});to.set(key,reverse);ctx.state().board=JSON.parse(entry.state);ctx.host.save();return redraw();}
 case 'zoom-in':return zoom(.5);case 'zoom-out':return zoom(2);case 'fit':return change('Fit depth',()=>{b.range=null;for(const w of b.wells)w.range=null;});
 case 'link':return change('Toggle linked depths',()=>{b.linked=!b.linked;for(const w of b.wells){w.range=w.range||b.range||fitRange();w.linked=b.linked;}});
 case 'tops':return change('Toggle top picking',()=>b.pickTop=!b.pickTop);case 'correlate':return change('Toggle top correlations',()=>b.correlation=!b.correlation);
 case 'flatten':return brandedForm('Flatten on a picked formation top',`<label class="field">Marker<select name="name"><option value="">No flattening</option>${[...new Set(b.markers.map(m=>m.name))].map(n=>`<option ${b.flatten===n?'selected':''}>${esc(n)}</option>`).join('')}</select></label><p>Only wells with this user-picked top receive an offset. Source depths are unchanged.</p>`,f=>change('Formation flattening',()=>{b.flatten=f.get('name')||null;b.range=null;}));
 case 'empty-track':if(!well)throw new Error('Select a well first.');return change('Add track',()=>{const t={id:uid(),name:'New track',width:140,curves:[]};well.tracks.push(t);b.selected={wellId:well.id,trackId:t.id};});
 case 'duplicate-track':if(!track)throw new Error('Select a track first.');return change('Duplicate track',()=>{const copy=structuredClone(track);copy.id=uid();copy.name+=' copy';for(const c of copy.curves)c.id=uid();well.tracks.splice(well.tracks.indexOf(track)+1,0,copy);b.selected={wellId:well.id,trackId:copy.id};});
 case 'duplicate-curve':if(!curve)throw new Error('Select a curve first.');return change('Duplicate overlay',()=>{const copy={...curve,id:uid(),name:curve.name+' copy',dashed:true};track.curves.push(copy);b.selected.curveId=copy.id;});
 case 'remove-track':if(track)return change('Remove track display',()=>{well.tracks=well.tracks.filter(t=>t.id!==track.id);b.selected={wellId:well.id};});return;
 case 'remove-curve':if(curve)return change('Remove curve display',()=>{track.curves=track.curves.filter(c=>c.id!==curve.id);delete b.selected.curveId;});return;
 case 'properties':s.focus='logs';ctx.state().inspector=true;return redraw();case 'curve-export':if(curve)return exportCurve(curve);throw new Error('Select a curve first.');case 'provenance':if(curve)return provenance(curve);throw new Error('Select a curve first.');
 case 'calculate':return ctx.chooseMethod();case 'back-to-logs':s.focus='logs';ctx.host.save();return redraw();case 'close-crossplot':return change('Close crossplot',()=>{b.crossplot=null;b.brush=null;});case 'clear-selection':return change('Clear selected samples',()=>{b.selectionRange=null;b.brush=null;});
 default:throw new Error('This canvas action is not available.');
}}

export function bindWellCanvas(){
 const root=document.querySelector('.iw');if(!root)return;
 if(!outsideBound){outsideBound=true;document.addEventListener('pointerdown',event=>{if(!event.target.closest('#wb-context-menu'))document.querySelector('#wb-context-menu')?.remove();});}
 const safe=fn=>async e=>{try{await fn(e);}catch(error){fail(error);}};root.querySelectorAll('[data-wb-tree-key]').forEach(details=>details.ontoggle=()=>{const set=new Set(board().treeOpen||[]);const before=set.has(details.dataset.wbTreeKey);if(details.open)set.add(details.dataset.wbTreeKey);else set.delete(details.dataset.wbTreeKey);if(before!==details.open){board().treeOpen=[...set];ctx.host.save();}});
 root.querySelectorAll('[data-wb-action]').forEach(button=>button.onclick=safe(()=>action(button.dataset.wbAction)));
 root.querySelectorAll('[data-wb-book]').forEach(button=>button.onclick=()=>{board().activeBook=button.dataset.wbBook;board().focus='logs';ctx.host.save();redraw();});
 root.querySelectorAll('[data-wb-open-well]').forEach(button=>button.onclick=e=>{e.preventDefault();e.stopPropagation();openWell(button.dataset.wbOpenWell);});
 root.querySelectorAll('[data-wb-import-well]').forEach(button=>button.onclick=safe(()=>ctx.host.openImporter({family:'logs',well:button.dataset.wbImportWell})));
 root.querySelectorAll('[data-wb-add-curve]').forEach(button=>button.onclick=safe(()=>{const [datasetId,columnId]=button.dataset.wbAddCurve.split(':');addToTrack({kind:'curve',datasetId,columnId},selectedObjects(book()).well?.id,selectedObjects(book()).track?.id);}));
 root.querySelectorAll('[data-wb-select]').forEach(button=>button.onclick=e=>{if(e.target.closest('[data-wb-well-menu]'))return;const picked=JSON.parse(button.dataset.wbSelect);const w=book().wells.find(w=>w.id===picked.wellId),t=w?.tracks.find(t=>t.id===picked.trackId),c=t?.curves.find(c=>c.id===picked.curveId);if(w)select(w,t,c);});
 root.querySelectorAll('[data-wb-new-track]').forEach(button=>button.onclick=()=>{book().selected={wellId:button.dataset.wbNewTrack};action('empty-track');});
 root.querySelectorAll('[data-wb-insert]').forEach(button=>button.onclick=()=>{const [id,index]=button.dataset.wbInsert.split(':');change('Insert track',()=>book().wells.find(w=>w.id===id).tracks.splice(Number(index),0,{id:uid(),name:'New track',width:140,curves:[]}));});
 root.querySelectorAll('[data-wb-well-menu]').forEach(button=>button.onclick=()=>{const well=book().wells.find(w=>w.id===button.dataset.wbWellMenu);book().selected={wellId:well.id};ctx.host.modal('Manage well display',`<div class="project-menu"><button id="wb-well-properties">Display properties</button><button id="wb-remove-well">Remove well from this workbook</button><button id="wb-top-table">Review / edit formation tops</button></div><p>Source files, imported curves and registered well identity remain stored.</p>`);$('#wb-well-properties').onclick=()=>{$('#dialog').close();select(well);};$('#wb-remove-well').onclick=()=>{change('Remove well display',()=>{book().wells=book().wells.filter(w=>w.id!==well.id);book().selected=null;});$('#dialog').close();};$('#wb-top-table').onclick=()=>topTable(well);});
 root.querySelectorAll('[data-wb-context]').forEach(element=>{element.oncontextmenu=e=>{e.preventDefault();e.stopPropagation();contextMenu(JSON.parse(element.dataset.wbContext),e.clientX,e.clientY);};element.onkeydown=e=>{if(e.key==='ContextMenu'||e.shiftKey&&e.key==='F10'){e.preventDefault();const r=element.getBoundingClientRect();contextMenu(JSON.parse(element.dataset.wbContext),r.left+20,r.top+10);}};});
 $('#wb-search')?.addEventListener('input',e=>{search=e.target.value;const pos=e.target.selectionStart;redraw();const input=$('#wb-search');input.focus();input.setSelectionRange(pos,pos);});
 root.querySelectorAll('[data-wb-drag]').forEach(element=>element.ondragstart=e=>{e.stopPropagation();e.dataTransfer.setData('application/x-stratax-object',element.dataset.wbDrag);e.dataTransfer.effectAllowed='copyMove';});
 root.querySelectorAll('[data-wb-drop]').forEach(element=>{element.ondragover=e=>{e.preventDefault();e.stopPropagation();element.classList.add('wb-drop-active');};element.ondragleave=()=>element.classList.remove('wb-drop-active');element.ondrop=safe(e=>{e.preventDefault();e.stopPropagation();element.classList.remove('wb-drop-active');const raw=e.dataTransfer.getData('application/x-stratax-object');if(!raw)return;const payload=JSON.parse(raw);addToTrack(payload,element.dataset.wellId,element.dataset.trackId);});});
 root.querySelectorAll('[data-wb-inspect]').forEach(button=>button.onclick=safe(async()=>{const dataset=ds(button.dataset.wbInspect);await ctx.inspectDataset(dataset);}));
 root.querySelectorAll('[data-wb-retry]').forEach(button=>button.onclick=safe(async()=>{failures.delete(button.dataset.wbRetry);await load(ds(button.dataset.wbRetry));redraw();}));
 root.querySelectorAll('[data-wb-review-run]').forEach(button=>button.onclick=safe(()=>ctx.reviewRun(button.dataset.wbReviewRun)));
 $('#wb-range')?.addEventListener('submit',safe(e=>{e.preventDefault();const f=new FormData(e.target),r=[Number(f.get('top')),Number(f.get('base'))];if(!validRange(r))throw new Error('Enter a finite base depth greater than the top.');change('Set displayed interval',()=>{const w=selectedObjects(book()).well;if(w?.linked===false)w.range=r;else book().range=r;});}));
 $('#wb-properties')?.addEventListener('submit',safe(e=>{e.preventDefault();const {well,track,curve}=selectedObjects(book()),f=new FormData(e.target),width=Number(f.get('width')||140),lo=f.get('min')===''?null:Number(f.get('min')),hi=f.get('max')===''?null:Number(f.get('max'));if(track&&(!Number.isFinite(width)||width<80||width>360))throw new Error('Track width must be 80–360 pixels.');if(curve&&(lo!==null&&!finite(lo)||hi!==null&&!finite(hi)||lo!==null&&hi!==null&&hi<=lo))throw new Error('Axis maximum must exceed its finite minimum.');if(curve&&f.has('log')&&(lo!==null&&lo<=0||hi!==null&&hi<=0))throw new Error('Logarithmic axis bounds must be positive.');change('Edit display properties',()=>{well.linked=f.has('linked');well.offset=Number(f.get('offset')||0);well.basis=f.get('basis');const target=curve||track||well;target.name=String(f.get('name')).trim();if(track)track.width=width;if(curve)Object.assign(curve,{color:f.get('color'),visible:f.has('visible'),log:f.has('log'),reverse:f.has('reverse'),dashed:f.has('dashed'),min:lo,max:hi,indexColumnId:f.get('indexColumnId')});});}));
 bindPlots(root);bindCrossplot();
}

function topTable(well){ctx.host.modal('Picked tops · '+esc(well.wellId),`<button id="wb-manual-top">Add top manually</button>${book().markers.filter(m=>m.wellId===well.wellId).map(m=>`<div class="status-row"><span>${esc(m.name)} · ${m.depth.toFixed(2)} m</span><button data-wb-edit-top="${m.id}">Edit</button><button data-wb-delete-top="${m.id}">Remove</button></div>`).join('')}`);$('#wb-manual-top').onclick=()=>pickTop(well,visibleRange(well)[0]+offsetFor(well));document.querySelectorAll('[data-wb-delete-top]').forEach(button=>button.onclick=()=>{change('Remove picked top',()=>book().markers=book().markers.filter(m=>m.id!==button.dataset.wbDeleteTop));topTable(well);});document.querySelectorAll('[data-wb-edit-top]').forEach(button=>button.onclick=()=>{const m=book().markers.find(m=>m.id===button.dataset.wbEditTop);brandedForm('Edit picked top',`<label class="field">Name<input name="name" required value="${esc(m.name)}"></label><label class="field">Depth (m)<input name="depth" type="number" step="any" required value="${m.depth}"></label><label class="field">Evidence notes<textarea name="notes" required>${esc(m.notes)}</textarea></label>`,f=>change('Edit picked top',()=>Object.assign(m,{name:f.get('name'),depth:Number(f.get('depth')),notes:f.get('notes')})));});}
function bindPlots(root){root.querySelectorAll('[data-wb-plot]').forEach(plot=>{const well=book().wells.find(w=>w.id===plot.dataset.wellId),track=well.tracks.find(t=>t.id===plot.dataset.wbPlot);const depthAt=e=>{const r=plot.getBoundingClientRect(),range=visibleRange(well);return range[0]+Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))*(range[1]-range[0])+offsetFor(well);};plot.onclick=e=>{if(plot.dataset.justSelected==='1'){plot.dataset.justSelected='0';return;}const depth=depthAt(e);book().selected={wellId:well.id,trackId:track.id,curveId:track.curves[0]?.id};if(book().pickTop){pickTop(well,depth);return;}const values=track.curves.map(c=>{const source=cache.get(c.datasetId);if(!source)return '';const di=source.columns.findIndex(v=>v.id===c.indexColumnId),ci=source.columns.findIndex(v=>v.id===c.columnId),factor=depthFactor(sourceUnit(source.columns[di]));if(!factor)return '';let nearest=null,delta=Infinity;for(const row of source.rows){const gap=Math.abs(row[di]*factor-depth);if(gap<delta){nearest=row;delta=gap;}}return c.name+': '+(finite(nearest?.[ci])?Number(nearest[ci].toPrecision(6)):'null')+' '+(c.unit||'unit unresolved');}).filter(Boolean);board().cursor=depth.toFixed(3)+' m · '+values.join(' · ');board().focus='logs';ctx.host.save();redraw();};
 plot.onpointermove=e=>{const depth=depthAt(e)-offsetFor(well);for(const line of root.querySelectorAll('.wb-cursor-line')){const targetWell=book().wells.find(w=>w.id===line.closest('[data-well-id]').dataset.wellId),range=visibleRange(targetWell),y=(depth-range[0])/(range[1]-range[0])*620;line.setAttribute('y1',y);line.setAttribute('y2',y);}};
 plot.onwheel=e=>{if(!e.ctrlKey&&!e.metaKey&&!e.shiftKey)return;if(!wellExtent(well))return;e.preventDefault();if(e.shiftKey){const range=visibleRange(well),delta=(range[1]-range[0])*.15*Math.sign(e.deltaY);change('Pan depth',()=>{const next=[range[0]+delta,range[1]+delta];if(well.linked===false)well.range=next;else book().range=next;});}else zoom(e.deltaY>0?1.2:1/1.2,depthAt(e)-offsetFor(well),well);};
 plot.onpointerdown=e=>{if(!e.shiftKey)return;e.preventDefault();const top=depthAt(e);plot.setPointerCapture(e.pointerId);const finish=ev=>{plot.removeEventListener('pointerup',finish);plot.dataset.justSelected='1';const base=depthAt(ev);if(Math.abs(base-top)>.0001)change('Select depth interval',()=>{book().selectionRange={top:Math.min(top,base),base:Math.max(top,base)};book().brush=null;book().selected={wellId:well.id,trackId:track.id,curveId:track.curves[0]?.id};});};plot.addEventListener('pointerup',finish);};
 plot.onkeydown=e=>{if(['+','=','-'].includes(e.key)){e.preventDefault();zoom(e.key==='-'?2:.5,null,well);}if(e.key==='Enter')select(well,track,track.curves[0]);};});}
function bindCrossplot(){const svg=$('#wb-crossplot-svg');if(!svg)return;svg.onpointerdown=e=>{e.preventDefault();const r=svg.getBoundingClientRect(),point=ev=>[(ev.clientX-r.left)/r.width*600,(ev.clientY-r.top)/r.height*300],start=point(e);svg.setPointerCapture(e.pointerId);const rect=$('#wb-brush-rect'),move=ev=>{const p=point(ev);rect.setAttribute('x',Math.min(start[0],p[0]));rect.setAttribute('y',Math.min(start[1],p[1]));rect.setAttribute('width',Math.abs(start[0]-p[0]));rect.setAttribute('height',Math.abs(start[1]-p[1]));};const finish=ev=>{svg.removeEventListener('pointermove',move);svg.removeEventListener('pointerup',finish);const end=point(ev),xmin=Number(svg.dataset.xmin),xmax=Number(svg.dataset.xmax),ymin=Number(svg.dataset.ymin),ymax=Number(svg.dataset.ymax),x=v=>xmin+(v-45)/525*(xmax-xmin),y=v=>ymin+(260-v)/240*(ymax-ymin);change('Brush crossplot samples',()=>{book().brush={...book().crossplot,xmin:Math.min(x(start[0]),x(end[0])),xmax:Math.max(x(start[0]),x(end[0])),ymin:Math.min(y(start[1]),y(end[1])),ymax:Math.max(y(start[1]),y(end[1]))};book().selectionRange=null;});};svg.addEventListener('pointermove',move);svg.addEventListener('pointerup',finish);};}

export function addAcceptedResults(runId){const accepted=data().filter(d=>d.scientificRunId===runId&&!d.isProposal&&indexColumn(d));if(!accepted.length)return;change('Add accepted calculated curves',()=>{ctx.state().proposals=(ctx.state().proposals||[]).filter(d=>d.scientificRunId!==runId);for(const dataset of accepted){const well=book().wells.find(w=>w.wellId===dataset.well)||addWell(book(),dataset.well||'Calculated evidence',[]),index=indexColumn(dataset);for(const c of numericColumns(dataset).filter(c=>c.id!==index.id))if(!well.tracks.some(t=>t.curves.some(v=>v.datasetId===dataset.id&&v.columnId===c.id)))addCurve(well,dataset,c.id);}board().focus='logs';});}
export function showProposal(runId,result){const indexed=result.datasets.filter(d=>indexColumn(d));if(!indexed.length)throw new Error('This result has no reviewed depth index. Use its table/array view; no log depth will be invented.');change('Preview full indexed proposal',()=>{ctx.state().proposals||=[];for(const d of indexed){const {preview,...manifest}=d;const entry={...structuredClone(manifest),family:'derived',isProposal:true,scientificRunId:runId,status:'Proposed · not accepted'};ctx.state().proposals=ctx.state().proposals.filter(p=>p.id!==d.id);ctx.state().proposals.push(entry);const well=book().wells.find(w=>w.wellId===d.well)||addWell(book(),d.well||'Unassigned calculated evidence',[]);for(const c of numericColumns(entry).filter(c=>c.id!==entry.indexColumnId))if(!well.tracks.some(t=>t.curves.some(v=>v.datasetId===entry.id&&v.columnId===c.id)))addCurve(well,entry,c.id);}board().focus='logs';});}
